  console.log("after public", JSON.stringify(afterPublic.settings));

  const afterFalsy = await updateOrganization(a.actors.admin, {
    orgId: a.org.id,
    settings: {
      digestHourUtc: 0,
      requireTwoFactor: false,
      enabledFlagOverrides: [],
    },
  });
  console.log("after falsy", JSON.stringify(afterFalsy.settings));

  const renamed = await updateOrganization(a.actors.admin, {
    orgId: a.org.id,
    name: "Alpha renamed",
  });
  console.log("after rename", renamed.name, JSON.stringify(renamed.settings));

  const other = await orgRepo.findOrgById(b.org.id);
  console.log("other org", other?.name, JSON.stringify(other?.settings));
} finally {
  cleanup();
}

